<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo e($mype->name); ?> | CloudBiz</title><?php echo app('Illuminate\Foundation\Vite')(['resources/css/app.css','resources/js/app.js']); ?></head><body class="bg-slate-50 text-slate-900"><header class="bg-emerald-950 text-white"><div class="mx-auto max-w-6xl px-5 py-6 flex flex-wrap items-center justify-between gap-4"><div class="cb-shop-brand"><?php if($mype->logo): ?><img src="<?php echo e(asset('storage/'.$mype->logo)); ?>" alt="Logotipo de <?php echo e($mype->name); ?>"><?php endif; ?><div><p class="text-xs text-emerald-300 uppercase tracking-widest">CloudBiz MYPES Perú</p><h1 class="text-2xl font-bold"><?php echo e($mype->name); ?></h1></div></div><span class="text-sm">Catálogo de productos</span></div></header><section class="bg-emerald-900 text-white"><div class="mx-auto max-w-6xl px-5 py-14"><p class="text-emerald-200 font-semibold">Tu tienda, más cerca de ti</p><h2 class="mt-2 text-4xl font-black max-w-2xl">Descubre nuestros productos</h2><p class="mt-3 text-emerald-100">Explora el catálogo y consulta por WhatsApp.</p><form method="GET" class="mt-6 flex max-w-xl gap-2"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Buscar productos..." class="w-full rounded-xl bg-white px-4 py-3 text-slate-900"><button class="rounded-xl bg-amber-400 px-6 py-3 font-bold text-slate-950">Buscar</button></form></div></section><main class="mx-auto max-w-6xl px-5 py-10"><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"><?php $__empty_1 = true; $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="overflow-hidden rounded-2xl bg-white shadow-sm border border-slate-200"><div class="h-52 bg-emerald-50 flex items-center justify-center overflow-hidden"><?php if($product->image): ?><img class="h-full w-full object-cover" src="<?php echo e(asset('storage/'.$product->image)); ?>" alt="<?php echo e($product->name); ?>"><?php else: ?><img class="h-32 w-32 object-contain opacity-80" src="<?php echo e(asset('images/producto.svg')); ?>" alt="Imagen ilustrativa de producto"><?php endif; ?></div><div class="p-5"><h3 class="font-bold text-lg"><?php echo e($product->name); ?></h3><p class="mt-2 text-sm text-slate-500 line-clamp-2"><?php echo e($product->description); ?></p><p class="mt-4 text-2xl font-black text-emerald-800">S/ <?php echo e(number_format($product->sale_price,2)); ?></p><p class="text-xs text-slate-500 mb-4"><?php echo e($product->stock > 0 ? 'Disponible' : 'Agotado'); ?></p><?php if($mype->phone && $product->stock > 0): ?><a class="block rounded-xl bg-emerald-700 p-3 text-center text-white font-semibold hover:bg-emerald-800" target="_blank" rel="noopener" href="https://wa.me/<?php echo e(preg_replace('/\D/','',$mype->phone)); ?>?text=<?php echo e(urlencode('Hola, deseo consultar por '.$product->name.' de '.$mype->name)); ?>">Consultar por WhatsApp ↗</a><?php else: ?><p class="rounded-xl bg-slate-100 p-3 text-center text-sm"><?php echo e($product->stock ? 'Consulta en tienda' : 'Sin stock'); ?></p><?php endif; ?></div></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><p class="text-slate-500 col-span-full">No se encontraron productos.</p><?php endif; ?></div><div class="mt-8"><?php echo e($products->links()); ?></div></main><footer class="border-t bg-white py-6 text-center text-sm text-slate-500"><?php echo e($mype->name); ?> · Catálogo creado con CloudBiz</footer></body></html>
